module Enumerable
  # No need to modify Enumerable; it already has map, select, sum, count, etc.
end

class SparseArray
  include Enumerable

  def initialize
    @data = {}
    @sorted_keys = nil
  end

  def []=(index, value)
    @data[index] = value
    @sorted_keys = nil # Invalidate sorted keys cache
    value
  end

  def [](index)
    @data[index]
  end

  def each(&block)
    return enum_for(:each) unless block_given?

    if @sorted_keys.nil?
      @sorted_keys = @data.keys.sort
    end

    @sorted_keys.each do |key|
      yield @data[key]
    end
    self
  end
end
