class OpenRecord
  def initialize(**attrs)
    @attrs = {}
    attrs.each do |k, v|
      set_attr(k, v)
    end
  end

  def method_missing(name, *args, &block)
    name_str = name.to_s
    if name_str.end_with?('=')
      attr_name = name_str[0..-2]
      unless args.size == 1
        raise ArgumentError, "wrong number of arguments (given #{args.size}, expected 1)"
      end
      set_attr(attr_name, args.first)
    elsif name_str.end_with?('!')
      raise NoMethodError, "undefined method `#{name_str}' for #{inspect}"
    elsif @attrs.key?(name_str)
      @attrs[name_str]
    else
      raise NoMethodError, "undefined method `#{name_str}' for #{inspect}"
    end
  end

  def respond_to_missing?(name, include_private = false)
    name_str = name.to_s
    if name_str.end_with?('=')
      attr_name = name_str[0..-2]
      @attrs.key?(attr_name) || super
    elsif @attrs.key?(name_str)
      true
    else
      super
    end
  end

  private

  def set_attr(name, value)
    @attrs[name.to_s] = value
    define_singleton_method(name.to_s) { @attrs[name.to_s] }
    define_singleton_method("#{name}=") { |v| @attrs[name.to_s] = v }
  end
end
