class KeyStore
  def initialize
    @data = {}
  end

  def store(key, value)
    @data[key] = value
    value
  end

  def fetch(key)
    if @data.key?(key)
      @data[key]
    else
      if block_given?
        yield
      else
        nil
      end
    end
