class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    entry = { payload: payload, stale: stale }
    if @packer
      stored = @packer.dump(entry)
      @store[key] = stored
    else
      @store[key] = entry
    end
    nil
  end

  def read(key)
    return nil unless @store.key?(key)
    entry = retrieve_entry(key)
    entry[:payload]
  end

  def sweep
    keys_to_delete = []
    @store.each_key do |key|
      entry = retrieve_entry(key)
      if entry[:stale]
        keys_to_delete << key
      end
    end
    keys_to_delete.each do |key|
      @store.delete(key)
    end
  end

  private

  def retrieve_entry(key)
    stored = @store[key]
    if @packer
      @packer.load(stored)
    else
      stored
    end
  end
end
