class Counter
  attr_reader :value, :step

  def initialize
    @value = 0
    @step = 1
  end

  def initialize_copy(other)
    super
    @value = other.instance_variable_get(:@value)
    @step = other.instance_variable_get(:@step)
  end

  def bump
    @value += @step
    self
  end

  def with_step(step)
    old_step = @step
    @step = step
    yield self
  ensure
    @step = old_step
  end
end
