class KeyStore
  def initialize
    @store = {}
  end

  def store(key, value)
    @store[key] = value
    value
  end

  def fetch(key, &block)
    if @store.key?(key)
      @store[key]
    elsif block_given?
      block.call
    else
      nil
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    if @store.key?(key)
      @hits += 1
      if block_given?
        # Block is passed but key was found, return stored value
        # The contract says: returns value already stored if key was previously stored
        # It calls block only when key was NOT stored. But wait, re-reading:
        # "returns the value already stored under key if key was previously stored via #store"
        # This implies if it is stored, we return it and DON'T call the block.
        @store[key]
      else
        @store[key]
      end
    else
      @misses += 1
      if block_given?
        block.call
      else
        nil
      end
    end
  end
end
